-- FILE: 0023_payment_lifecycle.sql
-- Apply later after schema review. All functions are service-role only.
create table if not exists public.checkout_payment_state (
  checkout_id text primary key,
  kind text not null check (kind in ('tokens','booking','live')),
  user_id uuid not null references auth.users(id),
  gross_cents integer not null check (gross_cents >= 0),
  fee_cents integer not null check (fee_cents >= 0),
  refunded_cents integer not null default 0 check (refunded_cents >= 0),
  quantity integer not null default 0,
  created_at timestamptz not null default now()
);
alter table public.checkout_payment_state enable row level security;
revoke all on public.checkout_payment_state from anon, authenticated;

create or replace function public.apply_paid_token_checkout(p_checkout_id text,p_user_id uuid,p_tokens integer,p_gross_cents integer,p_fee_cents integer)
returns void language plpgsql security definer set search_path = public as $$
begin
  if p_tokens not between 1 and 100 or p_gross_cents < 0 or p_fee_cents < 0 then raise exception 'Invalid checkout'; end if;
  insert into public.checkout_payment_state(checkout_id,kind,user_id,gross_cents,fee_cents,quantity)
  values(p_checkout_id,'tokens',p_user_id,p_gross_cents,p_fee_cents,p_tokens)
  on conflict do nothing;
  if not found then return; end if;
  update public.profiles set tokens=tokens+p_tokens,
    ledger=jsonb_build_array(jsonb_build_object('id',p_checkout_id,'label','Bought '||p_tokens||' tokens','tokens',p_tokens,'date',current_date,'netPerToken',(p_gross_cents-p_fee_cents)/p_tokens)) || ledger
  where id=p_user_id;
  if not found then raise exception 'Profile not found'; end if;
end $$;

create or replace function public.apply_paid_private_booking(p_checkout_id text,p_user_id uuid,p_trainer_id text,p_day text,p_time text,p_gross_cents integer,p_fee_cents integer,p_trainer_cents integer)
returns void language plpgsql security definer set search_path = public as $$
begin
  if p_day !~ '^\d{4}-\d{2}-\d{2}$' or p_time !~ '^\d{2}:\d{2}$' or p_gross_cents < p_fee_cents or p_trainer_cents < 0 then raise exception 'Invalid booking'; end if;
  insert into public.checkout_payment_state(checkout_id,kind,user_id,gross_cents,fee_cents)
  values(p_checkout_id,'booking',p_user_id,p_gross_cents,p_fee_cents)
  on conflict do nothing;
  if not found then return; end if;
  insert into public.trainer_busy(trainer_id,day,time,source)
  values(p_trainer_id,p_day::date,p_time,'booked');
  update public.profiles set bookings=jsonb_build_array(jsonb_build_object('id',p_checkout_id,'trainerId',p_trainer_id,'date',p_day,'time',p_time,'price',p_gross_cents/100.0,'paid',true)) || bookings
  where id=p_user_id;
  if not found then raise exception 'Profile not found'; end if;
  insert into public.trainer_earnings(trainer_slug,source,ref,gross_cents,fee_cents,net_cents,share_pct,payout_cents)
  values(p_trainer_id,'oneonone',p_checkout_id,p_gross_cents,p_fee_cents,p_gross_cents-p_fee_cents,90,p_trainer_cents)
  on conflict(ref) do nothing;
end $$;

create or replace function public.apply_paid_live_checkout(p_checkout_id text,p_user_id uuid,p_session_id uuid,p_gross_cents integer,p_fee_cents integer)
returns void language plpgsql security definer set search_path = public as $$
declare v_trainer text;
begin
  if p_gross_cents < p_fee_cents then raise exception 'Invalid fees'; end if;
  select trainer_id::text into v_trainer from public.live_sessions where id=p_session_id;
  if v_trainer is null then raise exception 'Unknown session'; end if;
  insert into public.checkout_payment_state(checkout_id,kind,user_id,gross_cents,fee_cents)
  values(p_checkout_id,'live',p_user_id,p_gross_cents,p_fee_cents)
  on conflict do nothing;
  if not found then return; end if;
  insert into public.live_room_access(session_id,user_id,stripe_checkout_session_id,status)
  values(p_session_id,p_user_id,p_checkout_id,'paid')
  on conflict(session_id,user_id) do update set status='paid',stripe_checkout_session_id=excluded.stripe_checkout_session_id;
  insert into public.trainer_earnings(trainer_slug,source,ref,gross_cents,fee_cents,net_cents,share_pct,payout_cents)
  values(v_trainer,'live',p_checkout_id,p_gross_cents,p_fee_cents,p_gross_cents-p_fee_cents,50,(p_gross_cents-p_fee_cents)/2)
  on conflict(ref) do nothing;
end $$;

-- Refunds are cumulative per checkout. Full refunds revoke access and reverse untransferred earnings.
create or replace function public.apply_checkout_refund(p_checkout_id text,p_refund_cents integer,p_fully_refunded boolean)
returns void language plpgsql security definer set search_path = public as $$
declare v public.checkout_payment_state%rowtype;
begin
  select * into v from public.checkout_payment_state where checkout_id=p_checkout_id for update;
  if not found then return; end if;
  if p_refund_cents <= v.refunded_cents then return; end if;
  update public.checkout_payment_state set refunded_cents=p_refund_cents where checkout_id=p_checkout_id;
  if p_fully_refunded then
    if v.kind='tokens' then
      update public.profiles set tokens=greatest(0,tokens-v.quantity) where id=v.user_id;
    elsif v.kind='booking' then
      delete from public.trainer_busy where source='booked' and (trainer_id,day,time) in
        (select b->>'trainerId',(b->>'date')::date,b->>'time' from public.profiles p,
          lateral jsonb_array_elements(p.bookings) b where p.id=v.user_id and b->>'id'=p_checkout_id);
      update public.profiles set bookings=(select coalesce(jsonb_agg(b),'[]'::jsonb) from jsonb_array_elements(bookings) b where b->>'id'<>p_checkout_id) where id=v.user_id;
    elsif v.kind='live' then
      update public.live_room_access set status='refunded' where stripe_checkout_session_id=p_checkout_id;
    end if;
    delete from public.trainer_earnings where ref=p_checkout_id and status='pending';
  end if;
end $$;

revoke all on function public.apply_paid_token_checkout(text,uuid,integer,integer,integer) from public,anon,authenticated;
revoke all on function public.apply_paid_private_booking(text,uuid,text,text,text,integer,integer,integer) from public,anon,authenticated;
revoke all on function public.apply_paid_live_checkout(text,uuid,uuid,integer,integer) from public,anon,authenticated;
revoke all on function public.apply_checkout_refund(text,integer,boolean) from public,anon,authenticated;
grant execute on function public.apply_paid_token_checkout(text,uuid,integer,integer,integer) to service_role;
grant execute on function public.apply_paid_private_booking(text,uuid,text,text,text,integer,integer,integer) to service_role;
grant execute on function public.apply_paid_live_checkout(text,uuid,uuid,integer,integer) to service_role;
grant execute on function public.apply_checkout_refund(text,integer,boolean) to service_role;


-- FILE: 0024_water_break_sponsors.sql
-- First-party direct sponsor campaigns; payment and settlement must be reconciled by staff.
create table if not exists public.water_break_impressions (
 id uuid primary key default gen_random_uuid(),
 campaign_id uuid not null references public.water_break_campaigns(id),
 video_id uuid not null references public.trainer_videos(id),
 playback_id uuid not null, break_second integer not null check(break_second>=0),
 recorded_at timestamptz not null default now(),
 unique(campaign_id,video_id,playback_id,break_second)
);
alter table public.water_break_campaigns enable row level security;
alter table public.water_break_impressions enable row level security;
revoke all on public.water_break_campaigns,public.water_break_impressions from anon,authenticated;
create or replace function public.record_water_break_impression(p_campaign_id uuid,p_video_id uuid,p_break_second integer,p_playback_id uuid)
returns void language plpgsql security definer set search_path=public as $$
begin
 if not exists (select 1 from public.water_break_campaigns where id=p_campaign_id and active and (start_at is null or start_at<=now()) and (end_at is null or end_at>=now())) then raise exception 'Inactive campaign'; end if;
 if not exists (select 1 from public.trainer_videos where id=p_video_id and review_status='approved' and p_break_second = any(breaks)) then raise exception 'Unapproved video'; end if;
 insert into public.water_break_impressions(campaign_id,video_id,break_second,playback_id)
 values(p_campaign_id,p_video_id,p_break_second,p_playback_id) on conflict do nothing;
end $$;
revoke all on function public.record_water_break_impression(uuid,uuid,integer,uuid) from public,anon,authenticated;
grant execute on function public.record_water_break_impression(uuid,uuid,integer,uuid) to service_role;


-- FILE: 0025_live_recording_events.sql
-- Apply in the SQL phase after confirming public.live_sessions exists.
-- Metadata only: do not publish recordings until the trainer submits a video for review.
create table if not exists public.live_recordings (
  egress_id text primary key,
  session_id uuid not null references public.live_sessions(id) on delete cascade,
  trainer_id uuid not null references auth.users(id),
  status text not null check (status in ('processing','completed','failed')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists live_recordings_trainer_idx on public.live_recordings(trainer_id);
alter table public.live_recordings enable row level security;
revoke all on public.live_recordings from anon, authenticated;
DROP POLICY IF EXISTS "trainer can read own recording metadata" ON public.live_recordings;
create policy "trainer can read own recording metadata" on public.live_recordings
  for select to authenticated using (trainer_id = auth.uid());


-- FILE: 0026_verified_ads_atomic.sql
-- Apply at SQL phase AFTER 0022 and 0023. Revenue is credited only from trusted signed settlements.
CREATE OR REPLACE FUNCTION public.apply_verified_ad_settlement(
 p_network text,p_network_event_id text,p_video_id uuid,p_trainer_id uuid,
 p_break_second integer,p_gross_cents integer,p_fee_cents integer,p_trainer_cents integer)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
BEGIN
 IF p_gross_cents < 0 OR p_fee_cents < 0 OR p_fee_cents > p_gross_cents
    OR p_trainer_cents <> floor((p_gross_cents-p_fee_cents)*0.5)::integer THEN
   RAISE EXCEPTION 'Invalid advertising allocation'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.trainer_videos WHERE id=p_video_id AND user_id=p_trainer_id
   AND review_status='approved' AND p_break_second=ANY(breaks)) THEN
   RAISE EXCEPTION 'Ineligible workout/break'; END IF;
 INSERT INTO public.ad_settlement_events(network,network_event_id,video_id,trainer_id,
   break_second,gross_cents,fee_cents)
 VALUES(p_network,p_network_event_id,p_video_id,p_trainer_id,p_break_second,p_gross_cents,p_fee_cents)
 ON CONFLICT DO NOTHING;
 IF NOT FOUND THEN RETURN; END IF;
 INSERT INTO public.trainer_earnings(trainer_slug,source,ref,gross_cents,fee_cents,net_cents,share_pct,payout_cents)
 VALUES(p_trainer_id::text,'ads','ad:'||p_network||':'||p_network_event_id,
   p_gross_cents,p_fee_cents,p_gross_cents-p_fee_cents,50,p_trainer_cents);
END $$;
REVOKE ALL ON FUNCTION public.apply_verified_ad_settlement(text,text,uuid,uuid,integer,integer,integer,integer) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.apply_verified_ad_settlement(text,text,uuid,uuid,integer,integer,integer,integer) TO service_role;


-- FILE: 0027_refunds_transfer_reversals.sql
-- Apply after 0023. Preserve transfer history: refunded earnings must not be deleted.
ALTER TABLE public.trainer_earnings DROP CONSTRAINT IF EXISTS trainer_earnings_status_check;
ALTER TABLE public.trainer_earnings ADD CONSTRAINT trainer_earnings_status_check
 CHECK(status IN ('pending','paid','refunded','reversal_due','transferring'));
ALTER TABLE public.trainer_earnings ADD COLUMN IF NOT EXISTS transfer_reversed_cents integer NOT NULL DEFAULT 0;
ALTER TABLE public.trainer_earnings ADD COLUMN IF NOT EXISTS reversal_target_cents integer NOT NULL DEFAULT 0;
ALTER TABLE public.trainer_earnings DROP CONSTRAINT IF EXISTS earnings_reversal_bounds;
ALTER TABLE public.trainer_earnings ADD CONSTRAINT earnings_reversal_bounds
 CHECK(transfer_reversed_cents>=0 AND reversal_target_cents>=0 AND reversal_target_cents<=payout_cents);
-- Replace legacy function from 0023, making cumulative partial refunds idempotent and
-- allowing Stripe's transfer reversal worker to settle already-transferred earnings.
CREATE OR REPLACE FUNCTION public.apply_checkout_refund(p_checkout_id text,p_refund_cents integer,p_fully_refunded boolean)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v public.checkout_payment_state%ROWTYPE; e public.trainer_earnings%ROWTYPE; target integer;
BEGIN
 SELECT * INTO v FROM public.checkout_payment_state WHERE checkout_id=p_checkout_id FOR UPDATE;
 IF NOT FOUND THEN RETURN; END IF;
 IF p_refund_cents < 0 OR p_refund_cents > v.gross_cents THEN RAISE EXCEPTION 'Bad refund amount'; END IF;
 IF p_refund_cents <= v.refunded_cents THEN RETURN; END IF;
 UPDATE public.checkout_payment_state SET refunded_cents=p_refund_cents WHERE checkout_id=p_checkout_id;
 IF p_fully_refunded THEN
   IF v.kind='tokens' THEN
     UPDATE public.profiles SET tokens=greatest(0,tokens-v.quantity) WHERE id=v.user_id;
   ELSIF v.kind='booking' THEN
     DELETE FROM public.trainer_busy WHERE source='booked' AND (trainer_id,day,time) IN (
       SELECT b->>'trainerId',(b->>'date')::date,b->>'time' FROM public.profiles p,
       LATERAL jsonb_array_elements(coalesce(p.bookings,'[]'::jsonb)) b
       WHERE p.id=v.user_id AND b->>'id'=p_checkout_id
     );
     UPDATE public.profiles SET bookings=(SELECT coalesce(jsonb_agg(b),'[]'::jsonb)
       FROM jsonb_array_elements(coalesce(bookings,'[]'::jsonb)) b WHERE b->>'id'<>p_checkout_id)
       WHERE id=v.user_id;
     UPDATE public.private_session_access SET status='refunded' WHERE checkout_id=p_checkout_id;
   ELSIF v.kind='live' THEN
     UPDATE public.live_room_access SET status='refunded' WHERE stripe_checkout_session_id=p_checkout_id;
   END IF;
 END IF;
 SELECT * INTO e FROM public.trainer_earnings WHERE ref=p_checkout_id FOR UPDATE;
 IF FOUND THEN
   target := CASE WHEN v.gross_cents>0 THEN
     floor(e.payout_cents::numeric * p_refund_cents / v.gross_cents)::integer ELSE e.payout_cents END;
   IF e.transfer_id IS NOT NULL THEN
     UPDATE public.trainer_earnings SET reversal_target_cents=target,
       status=CASE WHEN target>transfer_reversed_cents THEN 'reversal_due' ELSE 'paid' END
       WHERE id=e.id;
   ELSE
     -- No transfer exists. Keep original payout for historical reconciliation, exclude fully refunded work.
     UPDATE public.trainer_earnings SET status=CASE WHEN p_fully_refunded THEN 'refunded' ELSE 'pending' END,
       reversal_target_cents=target WHERE id=e.id;
   END IF;
 END IF;
END $$;
REVOKE ALL ON FUNCTION public.apply_checkout_refund(text,integer,boolean) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.apply_checkout_refund(text,integer,boolean) TO service_role;


-- FILE: 0028_wallet_live_redemption.sql
-- Apply after 0023 and 0027. Atomic, paid-token-backed attendance; no client can mint paid access.
CREATE TABLE IF NOT EXISTS public.wallet_token_lots (
 id text PRIMARY KEY, user_id uuid NOT NULL REFERENCES auth.users(id),
 purchased integer NOT NULL CHECK (purchased>0), remaining integer NOT NULL CHECK (remaining>=0),
 gross_cents integer NOT NULL, fee_cents integer NOT NULL,
 created_at timestamptz NOT NULL DEFAULT now(),
 CHECK (remaining<=purchased)
);
ALTER TABLE public.wallet_token_lots ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.wallet_token_lots FROM anon,authenticated;
DROP POLICY IF EXISTS wallet_owner_read ON public.wallet_token_lots;
CREATE POLICY wallet_owner_read ON public.wallet_token_lots FOR SELECT TO authenticated USING(user_id=auth.uid());
GRANT SELECT ON public.wallet_token_lots TO authenticated;

CREATE OR REPLACE FUNCTION public.apply_paid_token_checkout(p_checkout_id text,p_user_id uuid,p_tokens integer,p_gross_cents integer,p_fee_cents integer)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
BEGIN
 IF p_tokens NOT BETWEEN 1 AND 100 OR p_gross_cents<p_fee_cents OR p_fee_cents<0 THEN RAISE EXCEPTION 'Invalid token purchase'; END IF;
 INSERT INTO public.checkout_payment_state(checkout_id,kind,user_id,gross_cents,fee_cents,quantity)
 VALUES(p_checkout_id,'tokens',p_user_id,p_gross_cents,p_fee_cents,p_tokens) ON CONFLICT DO NOTHING;
 IF NOT FOUND THEN RETURN; END IF;
 INSERT INTO public.wallet_token_lots(id,user_id,purchased,remaining,gross_cents,fee_cents)
 VALUES(p_checkout_id,p_user_id,p_tokens,p_tokens,p_gross_cents,p_fee_cents);
 UPDATE public.profiles SET tokens=coalesce(tokens,0)+p_tokens,
 ledger=jsonb_build_array(jsonb_build_object('id',p_checkout_id,'label','Bought '||p_tokens||' tokens',
 'tokens',p_tokens,'date',current_date,'netPerToken',(p_gross_cents-p_fee_cents)/p_tokens)) || coalesce(ledger,'[]'::jsonb)
 WHERE id=p_user_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'Profile not found'; END IF;
END $$;
REVOKE ALL ON FUNCTION public.apply_paid_token_checkout(text,uuid,integer,integer,integer) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.apply_paid_token_checkout(text,uuid,integer,integer,integer) TO service_role;

CREATE OR REPLACE FUNCTION public.redeem_paid_live_token(p_user_id uuid,p_session_id uuid)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_trainer uuid; v_balance integer; v_lot public.wallet_token_lots%ROWTYPE; v_net integer;
BEGIN
 SELECT trainer_id INTO v_trainer FROM public.live_sessions WHERE id=p_session_id AND starts_at>now()-interval '4 hours'
   AND starts_at<now()+interval '1 day';
 IF v_trainer IS NULL THEN RAISE EXCEPTION 'Class unavailable'; END IF;
 PERFORM 1 FROM public.profiles WHERE id=p_user_id FOR UPDATE;
 IF EXISTS(SELECT 1 FROM public.live_room_access WHERE user_id=p_user_id AND session_id=p_session_id AND status='paid') THEN RETURN; END IF;
 SELECT coalesce(tokens,0) INTO v_balance FROM public.profiles WHERE id=p_user_id;
 IF v_balance<1 THEN RAISE EXCEPTION 'No available tokens'; END IF;
 SELECT * INTO v_lot FROM public.wallet_token_lots WHERE user_id=p_user_id AND remaining>0
 ORDER BY created_at,id LIMIT 1 FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'No verified purchased tokens available'; END IF;
 v_net := floor((v_lot.gross_cents-v_lot.fee_cents)::numeric/v_lot.purchased)::integer;
 UPDATE public.wallet_token_lots SET remaining=remaining-1 WHERE id=v_lot.id;
 UPDATE public.profiles SET tokens=tokens-1 WHERE id=p_user_id;
 INSERT INTO public.live_room_access(session_id,user_id,status) VALUES(p_session_id,p_user_id,'paid')
 ON CONFLICT(session_id,user_id) DO UPDATE SET status='paid';
 INSERT INTO public.trainer_earnings(trainer_slug,source,ref,gross_cents,fee_cents,net_cents,share_pct,payout_cents)
 VALUES(v_trainer::text,'live','wallet:'||p_session_id::text||':'||p_user_id::text,
   floor(v_lot.gross_cents::numeric/v_lot.purchased)::integer,
   floor(v_lot.fee_cents::numeric/v_lot.purchased)::integer,v_net,50,floor(v_net*0.5)::integer)
 ON CONFLICT(ref) DO NOTHING;
END $$;
REVOKE ALL ON FUNCTION public.redeem_paid_live_token(uuid,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.redeem_paid_live_token(uuid,uuid) TO service_role;


