ON CONFLICT(id) DO UPDATE SET public=false,file_size_limit=least(coalesce(storage.buckets.file_size_limit,10485760),10485760),
 allowed_mime_types=ARRAY['application/pdf','image/jpeg','image/png','image/webp'];
